func TestParseMRPDiscount(t *testing.T) {
	cases := []struct {
		name         string
		html         string
		price        float64
		wantOK       bool
		wantMRP      float64
		wantDiscount float64
	}{
		{
			name:         "price MRP and explicit percent-off adjacent",
			html:         `<div><span>₹1,799</span><span>₹2,999</span><span>40% off</span></div>`,
			price:        1799,
			wantOK:       true,
			wantMRP:      2999,
			wantDiscount: 40,
		},
		{
			name:         "price and MRP without explicit percent label falls back to computed discount",
			html:         `<div><span>₹500</span><span>₹1,000</span></div>`,
			price:        500,
			wantOK:       true,
			wantMRP:      1000,
			wantDiscount: 50,
		},
		{
			name:   "price not found in text",
			html:   `<div><span>₹999</span></div>`,
			price:  1799,
			wantOK: false,
		},
		{
			name:   "price found but no larger amount nearby",
			html:   `<div><span>₹1,799</span></div>`,
			price:  1799,
			wantOK: false,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			doc, err := xhtml.Parse(strings.NewReader(tc.html))
			if err != nil {
				t.Fatalf("parsing fixture HTML: %v", err)
			}
			tokens := collectVisibleTextTokens(doc)
			mrp, discount, ok := parseMRPDiscount(visibleTextJoined(tokens), tc.price)
			if ok != tc.wantOK {
				t.Fatalf("ok = %v, want %v", ok, tc.wantOK)
			}
			if !tc.wantOK {
				return
			}
			if mrp != tc.wantMRP {
				t.Errorf("mrp = %v, want %v", mrp, tc.wantMRP)
			}
			if discount != tc.wantDiscount {
				t.Errorf("discount = %v, want %v", discount, tc.wantDiscount)
			}
		})
	}
}

func TestParseBankOffers(t *testing.T) {
	cases := []struct {
		name string
		html string
		want []flipkartOfferOut
	}{
		{
			name: "two offers in the verified-live shape",
			html: `
				<div>
					<h3>Bank offers</h3>
					<div>₹90 off</div>
					<button>Apply</button>
					<div>Flipkart Axis</div>
					<div>Credit Card • Cashback</div>
					<div>₹90 off</div>
					<button>Apply</button>
					<div>Flipkart Finance</div>
					<div>Flipkart Pay Later</div>
				</div>
			`,
			want: []flipkartOfferOut{
				{AmountOff: 90, Description: "Flipkart Axis Credit Card • Cashback"},
				{AmountOff: 90, Description: "Flipkart Finance Flipkart Pay Later"},
			},
		},
		{
			name: "no bank offers section present",
			html: `<div><h3>Similar products</h3><div>₹90 off</div></div>`,
			want: nil,
		},
		{
			name: "bank offers heading with no following entries",
			html: `<div><h3>Bank offers</h3><h3>Coupons for you</h3></div>`,
			want: nil,
		},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			doc, err := xhtml.Parse(strings.NewReader(tc.html))
			if err != nil {
				t.Fatalf("parsing fixture HTML: %v", err)
			}
			tokens := collectVisibleTextTokens(doc)
			got := parseBankOffers(tokens)
			if len(got) != len(tc.want) {
				t.Fatalf("got %d offers, want %d: %+v", len(got), len(tc.want), got)
			}
			for i := range got {
				if got[i] != tc.want[i] {
					t.Errorf("offer[%d] = %+v, want %+v", i, got[i], tc.want[i])
				}
			}
		})
	}
}

func TestParseBankOffersFromTrackingBlob(t *testing.T) {
	// Shaped after the real live analytics/tracking blob Flipkart embeds
	// alongside the (visually virtualized, empty-in-static-HTML) bank
	// offers carousel: repeated objects carrying contentType, contentTitle,
	// and a sibling discountedPriceText. Deliberately includes: a
	// duplicate-with-different-contentType entry (must be excluded), a
	// login-required variant with a leading underscore in contentTitle
	// (must normalize and dedupe against the plain variant), and an
	// unrelated section using the same discountedPriceText field shape.
	blob := `{"contentType":"OfferDetails:Bank offers","contentTitle":"Flipkart Axis_Credit Card • Cashback"},"value":{"discountedPriceText":"₹1,550 off"},"contentType":"OfferDetails:Bank offers","contentTitle":"_Flipkart Axis_Credit Card • Cashback","discountedPriceText":"₹1,550 off","contentType":"OfferDetails:Bank offers","contentTitle":"BHIM UPI_Cashback","discountedPriceText":"₹75 off","contentType":"OfferDetails:Coupons","contentTitle":"WELCOME50","discountedPriceText":"₹50 off"}`

	got := parseBankOffersFromTrackingBlob([]byte(blob))
	want := []flipkartOfferOut{
		{AmountOff: 1550, Description: "Flipkart Axis Credit Card • Cashback"},
		{AmountOff: 75, Description: "BHIM UPI Cashback"},
	}
	if len(got) != len(want) {
		t.Fatalf("got %d offers, want %d: %+v", len(got), len(want), got)
	}
	for i := range got {
		if got[i] != want[i] {
			t.Errorf("offer[%d] = %+v, want %+v", i, got[i], want[i])
		}
	}
}

func TestFormatRupeeAmount(t *testing.T) {
	cases := map[float64]string{
		500:     "500",
		1799:    "1,799",
		2999:    "2,999",
		100000:  "1,00,000",
		1234567: "12,34,567",
	}
	for v, want := range cases {
		if got := formatRupeeAmount(v); got != want {
			t.Errorf("formatRupeeAmount(%v) = %q, want %q", v, got, want)
		}
	}
}
